  "le":["li","ly"], "ke":["ki"], "nge":["ngi"], "pe":["pi"], "we":["wi"],
  "lle":["lli"], "fu":["fw","fuw"], "rke":["rki"], "ürke":["ürki"],
  "üwye":["uwye","wye"], "meke":["meki"], "künu":["kunu","kinu"],
  "nie":["ne","ni"], "uw":["u","w","uw"], "ñma":["ma","nma"], "üñma":["uñma","ñma"],
