RULED_ROOTS.push('wirar','wirarwirar');
RULED_ROOTS.push('chillka','pipi');   /* build136, analyst rulings 2026-11-04/05: chillka- is a root (chillka-tu-n, not
   chi-l-l-ka-tu-n); pipi- is a reduplicated root */   /* reduplicated root kept whole, as gold trawtraw-küle-we-y */
const DECOMPOSE={
  /* Decompose only where the base is independently attested as a free root in AVENUE,
     with productivity behind it. Figures are base tokens / distinct base wordforms. */
  'kimeltu':['kim','el','tu'],      /* kim 9871 / 1409 */
  'rupafem':['rupa','fem'],         /* rupa 1354 / 174 */
  'liftu':['lif','tu'],             /* lif 93 / 22 */
  'yow':['yo','w'],                 /* yo 87 / 6 */
  'chillkatu':['chillka','tu'],     /* chillka 53 / 25 */
  'pewtu':['pew','tu'],             /* pew 46 / 4 */
  'ngünaye':['ngüna','ye'],         /* nguena 40 / 35 */
  /* added on error evidence, round 2 */
  'kuñiwtun':['kuñiw','tu','n'],    /* kuñiw 16 tok / 14 wordforms, free 3 */
  'trepew':['trepe','w']            /* trepe 12 tok / 11 wordforms, free 2 — marginal, analyst-approved */
  /* EXCLUDED, base not independently attested: emür (emü 3 tokens, all inside emür), üre.
     PENDING analyst ruling: trepew (trepe 12 tokens / 11 wordforms, marginal). */
};
/* FIX 4: missing roots and orthographic variants that generate cascades of errors.
   yow (= llow) produced 5 of 71 errors in a 222-form sample from one missing entry. */
/* build71: yow added, a Pewenche variant of llow- 'receive' that the analyst
   identified in three gold corrections (yoweyu, yowkefimi, yownietuy). It is
   attested but not attestedStrong, while yo- is strong, so the ranker preferred
   yo-w- and no LEX_STEMS entry could reach it: that path runs only under the
   SINGLE_ROOTS override and yo is not a single root. Train +0.1, dev +0.7.
   pengel- was tested the same way and changed nothing, so it is not listed.
   pesaw was REMOVED in the same build: the analyst ruled pesawkuli as pesa-w-kul(e)-i,
   from Spanish pesar plus the reflexive -w-, so pesaw is not a stem and listing it here
   forced the wrong analysis on the one gold form that uses it. */
const ADD_ROOTS=['yow','llow','üre',   /* build136: emür removed, a truncated token (2026-11-05) */
  'defende','molesta','nase','pedi','fende','empesa'];

/* FIX 5: inverse and portmanteau endings the slot template does not decompose. */
/* build71: this table was dead code in every build from 43 on, defined and exported but
   never referenced, so none of its seven rules had ever fired. Wired up and measured on
   gold v15, six of the seven had to be removed:
     ['iñ',['i','ñ']]   the rule is BACKWARDS relative to current gold. It was written
                        against build 43's output, when the core over-split -iñ; the core
                        has since been fixed, the parser now produces iñ whole in 21 gold
                        forms, and re-splitting it broke all 21 and fixed none. Train
                        86.3% -> 84.6%. The table being dead is the only reason this did
                        not cost 1.7 points for twenty-odd builds.
     ['mu',['mu']]      fixed 0, broke 1. Gold is not consistent here: lüf-ün-m-u splits
                        it, wesaku-ne-y-in-mu and lladkü-tu-nu-el-i-mu keep it whole.
                        Listed in gold_inconsistencies_v15.csv rather than decided.
     ['yin',['y','in']] never fires. The forms it targets have -mu after the ending, so
                        -yin is not at the tail where this pass looks.
     eymu, enew, eyu    no effect; the core already produces these whole.
   Only ['yem',['yem']] survives: it fixes lüfiyem (lüf-i-ye-m -> lüf-i-yem) and breaks
   nothing. One form, kept because it is free and correct. */
const PORTMANTEAU=[ ['yem',['yem']], ['eymu',['eymu']], ['eymew',['eymew']] ];
/* build73: the eymu rule is back. Build 71 measured it as having no effect, correctly at
   the time: gold then split it four different ways. The analyst's paradigm charts
   (J. Becker Pena, supplied Oct 2026) give 3>2sg as -eymew, and the mew~mu reduction makes
   -eymu the same ending. The AVENUE translation tier settles it outright: all ~50 elueymu
   tokens are 'te dio' / 'le dio' / 'nos dio', kuñiwtuneymu is 'te cuido', kelluneymu is
   'lo ayuda a usted', witrakontukerkeeymu is 'te esta acogiendo'. Not one is a 2nd dual
   subject, and not one supports mu as a separate word. Gold v19 makes all six rows one
   ending and this rule makes the parser agree. */

/* FIX 2: Spanish participial adjectives borrowed as adjectives, not verbs.
   -ado/-ido borrowings are a closed class; forcing a verb parse invents morphology. */
const LOAN_ADJ=new Set(['pasau','pesau','kansau','koloraw','apuraw','listu','seguru','ultimu',
  'trankilu','kontentu','okupaw','kasaw','mojaw','asustaw','preokupaw']);

/* FIX 1: underlying-vowel notation.
   Build 42 writes the surface form where the analyst writes the underlying one:
   stem-final /e/ fuses with indicative /i/ (-kule + -i -> surface -kuli), and the
   nominaliser -el fuses after future -a (-a + -el -> surface -al). These are
   REPRESENTATION mismatches, not segmentation failures, but they change the morph
   count, so they are normalised here in the analyst's (e) convention. */
/* build44 fix 3: the underlying-vowel split is now licensed LEXICALLY rather than by
   surface shape. Build 43 split any surface -Ci into -C(e) + -i on a regex match, which
   over-applied: 19 of its 67 remaining errors were invented boundaries, -i added 10 times.
   The morph's base form must now be listed as e-final. */
/* REVERTED. The lexical licensing tried here tested the pre-i string against a set of
   e-final morph BASES, adding the x+'e' variant. That over-matched badly: for -mi the
   pre-i string is 'm', whose +e form 'me' is an e-final morph, so -mi (2sg) was split as
   -m(e)-i. Same for -wi, -fi, -ki. Accuracy fell 74.7% -> 71.3%, 17 forms broken.
   The build 43 regex is restored: it tests the pre-i string directly, which is the right
   unit, and does not admit the +e fallback. The invented-boundary errors that motivated
   this change have some other cause and remain open. */
const STEMFINAL_E=/^(kül|ng|l|le|nie|rk|k|mek|pe|we|kle)$/;
function isEfinalStem(x){ return STEMFINAL_E.test(x); }

/* build44 fix 4: non-verbal templates. femngechi, kangechi, kinechi, pichikeche were
   returned whole because the verbal slot template has no rules for adverbial -nge-chi
   or nominal -ke-che formations. Handled as their own patterns, gated on the base being
   independently attested. */
const NONVERB=[
  [/^(.+?)ngechi$/, m=>[m[1],'nge','chi']],
  [/^(.+?)kechi$/,  m=>[m[1],'ke','chi']],
  [/^(.+?)keche$/,  m=>[m[1],'ke','che']],
  [/^(.+?)chi$/,    m=>[m[1],'chi']]
];
function nonVerbParse(P,w){
  for(const [re_,f] of NONVERB){
    const m=re_.exec(w);
    if(!m || m[1].length<3) continue;
    let ok=false; try{ ok=P.attested && P.attested(m[1]); }catch(e){}
    if(!ok) continue;
    const parts=f(m);
    return {root:parts[0], m:parts.slice(1).map((x,i)=>({f:x,slot:i===0?36:30,gloss:'NV?',label:'build 44 non-verbal pattern, given verb slots'}))};
  }
  return null;
}
function restoreUnderlying(root,morphs){
  const out=[];
  for(let i=0;i<morphs.length;i++){
    const m=morphs[i];
    // surface -Ci where C-stem underlyingly ends in /e/  ->  -C(e) + -i
    const mm=/^(.*?)i$/.exec(m.f);
    if(mm && mm[1] && isEfinalStem(mm[1]) && i===morphs.length-1){
      out.push({f:mm[1]+'(e)',slot:m.slot}); out.push({f:'i',slot:2}); continue;
    }
    // surface -al / -am after a future -a  ->  -a + -(e)l / -a + -m
    if(/^a(l|m)$/.test(m.f)){
      out.push({f:'a',slot:9});
      out.push({f:(m.f.endsWith('l')?'(e)l':'m'),slot:m.slot}); continue;
    }
    // surface -wi  ->  -w + -i
    if(m.f==='wi'){ out.push({f:'w',slot:31}); out.push({f:'i',slot:2}); continue; }
    // surface -ni after a consonant-final root -> -ni + (y)
    out.push(m);
  }
  return out;
}
/* FIX 4b: roots that must NOT be decomposed. The base is not independently attested,
   so any split is spurious. emue occurs 3 times in the corpus, all inside emuer forms. */
const PROTECT=new Set(['üre','emu','üwe']);   /* build136: emür removed (truncated fem-/chem- + -ürke-) */

/* FIX 5: the -fi- satellite-person paradigm. Build 42 emits fused morphs for the three
   commonest combinations, hiding a boundary in 5,923 tokens. */
/* build51: the n-spelling of -fiñ. Once allomorphs() generates n for ñ (build50) the
   surface -fin matches slot 6 whole, so molesta-la-fin was returned where the -fi-
   ruling wants molesta-la-fi-n. Split it exactly as -fiñ is split. */
const FI_SPLIT_ON={'fiñ':['fi','ñ'],'fin':['fi','n'],'fimi':['fi','mi'],'fiel':['fi','el'],'fiyu':['fi','yu'],'fimün':['fi','mün']};
const FI_SPLIT_OFF={};
/* build76: OFF by default. Analyst ruling, Oct 2026: portmanteau endings are single
   units. The -fin worklist had only asked WHERE to split them, never whether, so this
   supersedes that answer. The core suffix table already carries fin, fimi, vin, vimi,
   eyu, enew, etew and eyew as slot 6 entries, so turning the split off lets the search
   find them directly instead of the patch layer breaking them apart afterwards. */
let FI_SPLIT=FI_SPLIT_OFF;
function setFiSplit(on){ FI_SPLIT = on?FI_SPLIT_ON:FI_SPLIT_OFF; }

/* build44 fix 2: the -n citation-form artefact.
   Augusta lists verbs under BOTH the bare root and the 1sg indicative citation form
   (muele AND muelen, kim AND kimuen), so both are in GLOSS and longest-root matching
   takes the citation form, returning muelen / kimuen / amun / pen unsegmented. The
   repair is scoped to the failure case only: it fires when the parse found NO suffix
   at all, the surface ends in -n or -uen, and the stripped form is independently
   attested. A root that genuinely ends in n (kon 'enter') is untouched, because
   stripping it does not yield an attested root. */
const REPARSE_OK=new Set(['le','küle','pa','pu','tu','nie','nge','yaw','r','che']);
function citationRepair(P,w,root,ms){
  if(ms.length) return null;
  const m=/^(.*?)(ün|n)$/.exec(w);
  if(!m || m[1].length<2) return null;
  const base=m[1];
  try{ if(!P.attested || !P.attested(base)) return null; }catch(e){ return null; }
  /* build86: re-parse the stripped base instead of accepting it whole (RANKING_HANDOFF
     section 57). The core returns a frequent inflected word whole because ROOTFREQ and the
     Augusta GLOSS both hold word forms (chumlen 149 tokens, an Augusta headword), so this
     repair used to stop at chumle-n, kimpa-n, mongetu-n, akutu-n: the root swallowing a
     derivational suffix, which is the error shape of every -n failure on the frequent-band
     supplement. Accepted only when the base re-parses into a root of 3+ letters that is
     attestedStrong, and every new morph is one of a closed set of transparent derivational
     suffixes. Without the 3-letter gate nie-n and yeme-n broke (ni-e-n, ye-m-e-n); without
     the suffix set 13 corpus types over-split (will-e-n, füren-e-n, truf-ke-n, tra-l-ka-n,
     pal-i-n, manel-uw-ün). rootAdjacent() and flex() are re-run on the whole list: run on
     the bare base, -nge- is final and keeps slot 36 (fem-nge:36-n), the one-ended-wiring
     bug of rule 7 again. */
  let q=null; try{ q=P.parse(base,'',3,false); }catch(e){}
  if(q && q.m && q.m.length && q.root.length>=3 && P.attestedStrong(q.root) &&
     q.m.every(x=>REPARSE_OK.has(x.f)) && q.root+q.m.map(x=>x.f).join('')===base)
    return {root:q.root,m:P.flex(P.rootAdjacent(q.m.concat([{f:m[2],slot:2}]),''))};
  /* build90: label the ending through flex(), as every other path does; it was returned bare and
     the app printed its gloss as 'undefined' (amu-n, kim-ün, pewma-n). */
  return {root:base,m:P.flex([{f:m[2],slot:2}])};
}

function portmanteau(ms){
  for(const [surf,parts] of PORTMANTEAU){
    for(let k=Math.min(4,ms.length); k>=1; k--){
      const tail=ms.slice(ms.length-k);
      if(tail.map(x=>x.f).join('')!==surf) continue;
      if(k===parts.length && tail.every((x,i)=>x.f===parts[i])) break;  /* already correct */
      const slot=tail[tail.length-1].slot;
      const rep=parts.map((f,i)=>({f, slot: i===parts.length-1 ? slot : tail[0].slot}));
      return ms.slice(0,ms.length-k).concat(rep);
    }
  }
  return ms;
}
/* build101: whole-word rulings (analyst, 2026-10-19). "fey llemay" is two words written as one: fey plus
   the particle llemay, which is itself a word, not lle-ma-y. chaltumay 'thanks' is one word and not a verb
   ("if it were to be divided it would be chaltu-may, but more as an adverb"); chaltu is taken whole on
   the same ruling (inferred, not ruled). femllimay is fem-lli-may "for now": fem plus affirmative -lli-
   (slot 11, as in femlli) with the particle may detached. Exact word forms only. */
const PTCL=(f,why)=>({f:f,gloss:'PTCL',note:why});
const WHOLE_WORDS={
  llemay:{root:'llemay',m:[],cat:'particle',flag:'not-a-verb'},
  llemai:{root:'llemai',m:[],cat:'particle',flag:'not-a-verb'},
  chaltumay:{root:'chaltumay',m:[],cat:'interjection',flag:'not-a-verb'},
  chaltumai:{root:'chaltumai',m:[],cat:'interjection',flag:'not-a-verb'},
  chaltu:{root:'chaltu',m:[],cat:'interjection',flag:'not-a-verb'}};
const JOINED_WORDS={feyllemay:['fey','llemay'],feyllemai:['fey','llemai'],veyllemay:['vey','llemay'],veyllemai:['vey','llemai']};
const PART_DETACH={femllimay:['femlli','may'],femllimai:['femlli','mai']};
/* the app runs orth() before parsing (ll -> y, v -> f), so every key is also entered in its orth() form;
   without this the rulings would hold in node and silently fail in the app (rule 7) */
for(const T of [WHOLE_WORDS,JOINED_WORDS,PART_DETACH]) for(const k of Object.keys(T)){ const o=P.orth(k); if(o!==k && !T[o]) T[o]=T[k]; }
if(P.GLOSS){ for(const [k,d] of [['chaltumay','Gracias'],['chaltumai','Gracias'],['chaltu','Gracias'],['llemay','pues, entonces (partícula)'],['llemai','pues, entonces (partícula)']])
  if(!P.GLOSS[k]) P.GLOSS[k]={d:d,src:'R'}; }
function parse43v(w,cat,mr,decomp){
  if(WHOLE_WORDS[w]) return Object.assign({},WHOLE_WORDS[w],{note:'analyst ruling 2026-10-19'});
  if(JOINED_WORDS[w]) return {root:JOINED_WORDS[w][0],m:[],cat:'particle',
    enclitic:PTCL(JOINED_WORDS[w][1],'separate word written joined: fey llemay (analyst ruling 2026-10-19)')};
  if(PART_DETACH[w]){ const q=parse43(PART_DETACH[w][0],cat,mr,decomp) || {};
    return Object.assign({},q,{enclitic:PTCL(PART_DETACH[w][1],'particle written joined: fem-lli-may (analyst ruling 2026-10-19)')}); }
  if(LOAN_ADJ.has(w)) return {root:w,m:[],cat:'adjective',flag:'loan-adjective'};
  let p=null;
  try{ p=P.parse(w,cat||'',mr||3,!!decomp); }catch(e){ return null; }
  if(!p) return null;
  let root=p.root, ms=(p.m||[]).slice();
  /* build44 fix 4 runs BEFORE the citation repair: an adverbial in -nge-chi ends in
     -i, not -n, so the two never compete, but ordering it first keeps the failure
     case (zero morphs found) handled in one place. */
  if(!ms.length){
    const nv=nonVerbParse(P,w);
    if(nv){ root=nv.root; ms=nv.m; }
  }
  const cr=citationRepair(P,w,root,ms);
  if(cr){ root=cr.root; ms=cr.m; }
  /* build88: roots the parser takes whole but gold v27 always splits (RANKING_HANDOFF section 59).
     The frequent-form errors that survive build 86 (amul-i, amule-n, mongele-n, ...) are a root
     that is a shorter attested root plus a derivational suffix. Whether to split is lexical
     (gold keeps ngillatu, kintu, treka, lladkütu whole), so no general rule: this table holds only
     the roots gold already splits, found by a corpus scan, with gold's own split. Other roots are
     out for ruling. The remainder after the split root is re-covered by segTail(); if that fails,
     the parse stands. */
  /* build94: the analyst's root rulings of 2026-10-15 (root_rulings_2026-10_RETURNED.xlsx): roots the
     parser took whole that are a root plus a derivational suffix. Same mechanism as GOLD_SPLIT. Roots ruled
     'whole' or 'a noun/adjective that verbalizes' (mongel, trür, tremole, mapuche, tripantu, montu, ...) are
     already whole and need no entry. */
  if(!GOLD_SPLIT[root] && RULED_SPLIT[root]){
    /* the ruling fixes the root and its first suffix; the rest of the word is segmented freely
       (holding only the root let segTail choose monge-l-eiñ for monge-le-iñ) */
    const r0=RULED_SPLIT[root][0], s1=RULED_SPLIT[root][1];
    let h=null, tl=null; try{ h=P.segTail(s1); }catch(e){}
    const rest=w.slice(r0.length+s1.length);
    if(rest){ try{ tl=P.segTail(rest); }catch(e){} } else tl=[];
    if(h && h.length===1 && tl){ root=r0; ms=P.flex(P.rootAdjacent(h.concat(tl),'')); if(p.enclitic) p.enclitic=null; }
  }
  /* build95: tralka- is the root (analyst ruling 2026-10-15); the bare noun tralka 'trueno' and
     tralkatu- were split tra-l-ka(-tu). A word beginning with a protected root takes that root and
     segTail() covers the rest; if the cover fails, the parse stands. */
  for(const pr of RULED_ROOTS){
    if(root!==pr && w.startsWith(pr)){
      /* keep a detached enclitic (müñetun + mu, tralkan + mu) and fix the root only in the word before it */
      const enc=p.enclitic && (p.enclitic.f||p.enclitic); const wb=(enc && w.endsWith(enc)) ? w.slice(0,w.length-enc.length) : w;
      const rest=wb.slice(pr.length); let tl=rest?null:[]; if(rest){ try{ tl=P.segTail(rest); }catch(e){} }
      if(tl){ root=pr; ms=P.flex(P.rootAdjacent(tl,'')); } }
  }
  /* build94: tremole- loses its final e before a vowel-initial suffix (ruling: "tremole-" is the root of
     tremolafiñ, tremolay): written tremol(e), which reconstructs to the surface. */
  if(root==='tremol' && ms[0] && /^[aeiouü]/.test(ms[0].f)) root='tremol(e)';
  /* build110: the root is tremo-, not tremole- (analyst ruling 2026-10-27, reversing 2026-10-15: "root is tremo- otherwise
     tremoley doesn't work"): tremo-le-y, tremo-l(e)-i, tremo-l(e)-a-fiñ. The -le- is the stative, slot 28. */
  if(/^tremol(e|\(e\))?$/.test(root)){
    const vow=ms[0] && /^[aeiouü]/.test(ms[0].f);
    root='tremo'; ms=[{f:vow?'l(e)':'le',base:'le',slot:28,label:'stative/prog',gloss:'STAT'}].concat(ms);
  }
  if(GOLD_SPLIT[root]){
    const r0=GOLD_SPLIT[root][0]; let tl=null; try{ tl=P.segTail(w.slice(r0.length)); }catch(e){}
    const want=GOLD_SPLIT[root].slice(1).join('');
    if(tl && tl.length && tl.map(x=>x.f).join('').startsWith(want)){
      root=r0; ms=P.flex(P.rootAdjacent(tl,'')); if(p.enclitic) p.enclitic=null; }
  }
  /* build91: a noun whose dictionary form ends in -n keeps it (analyst ruling 2026-10-14: "lamngen is not a
     verb. The n on the end is part of the entire noun"). The gloss table strips -n/-ün from every Augusta
     citation form, which is right for verbs (amun -> amu-) but leaves a phantom root for nouns (lamngen ->
     lamnge-, newen -> newe-, kutran -> kutra-), so the -n was read as 1sg. When the parse is root + -n/-ün
     alone and the whole word is a dictionary entry whose definition is not verbal, the word is the root. */
  if(ms.length===1 && ms[0].slot===2 && /^(n|ün)$/.test(ms[0].f) && root+ms[0].f===w && P.GLOSS && P.GLOSS[w] &&
     !isVerbDef(P.GLOSS[w].d)){ root=w; ms=[]; }
  /* build92: a dictionary stem in -ñma- whose base is a vowel-final verb is base + the indirect-object
     -ñma- (slot 26), not one root (analyst ruling 2026-10-14: perküñmawün is perkü-ñma-w-ün). Augusta lists
     such derived stems as headwords (perküñman 'tirarle un pedo a alguno'). Not a blanket split: reñma
     'family', puñma 'opposite' and weñma are lexical, and their bases are not verbs. */
  { const mm=/^(.{2,}[aeiouü])(ñma|nma)$/.exec(root);
    /* the app's orth() folds ll -> y before parsing (lladkü -> yadkü), so try the ll spelling as well */
    let g=null; if(mm && P.GLOSS) for(const v of [mm[1], mm[1].replace(/y/g,'ll'), mm[1].replace(/^y/,'ll')]){ g=P.GLOSS[v]||P.GLOSS[v+'n']||P.GLOSS[v+'\u00fcn']; if(g) break; }
    if(mm && P.GLOSS){
      /* build96: slot 35 (experiencer/oblique object) when a suffix of a higher slot follows (perkü-ñma-w-ün:
         -w- is 31), slot 26 otherwise. Build 92 always wrote 26, which put 26 before 31, against the template. */
      if(g && isVerbDef(g.d)){ root=mm[1]; const hi=ms.length && ms[0].slot>26;
        ms=P.flex(P.rootAdjacent([hi?{f:mm[2],slot:35,label:'experience/obl.obj',gloss:'EXP'}:{f:mm[2],slot:26,label:'indirect.obj',gloss:'IO'}].concat(ms),'')); } } }
  // FIX 3: decompose stored compound/derived stems
  /* FIX 4b: PROTECT works by RE-MERGING. Build 42 cannot be made to find a longer
     root, so where root + following morphs reconstruct a protected root, glue them
     back together. emue + -r- -> emuer, whose base emue is not independently attested. */
  for(let k=Math.min(2,ms.length); k>=1; k--){
    const cand=root+ms.slice(0,k).map(x=>x.f).join('');
    if(PROTECT.has(cand)){ root=cand; ms=ms.slice(k); break; }
  }
  if(PROTECT.has(root)){ /* leave root intact */ }
  else if(DECOMPOSE[root]){
    const parts=DECOMPOSE[root];
    if(parts.length>1){
      root=parts[0];
      for(let i=parts.length-1;i>=1;i--) ms.unshift({f:parts[i],slot:33});
    }
  }
  // FIX 5: split the fused -fi- person morphs
  const ms2=[];
  for(const m of ms){
    if(FI_SPLIT[m.f]){ const [a,b]=FI_SPLIT[m.f]; ms2.push({f:a,slot:6}); ms2.push({f:b,slot:2}); }
    else ms2.push(m);
  }
  ms=ms2;
  /* build71: ADD_ROOTS was dead code in the same way PORTMANTEAU was: defined and
     exported since build 43, never referenced, so its ten entries had never done
     anything. Wired up here as a prefix override, deliberately narrow because this is
     the sixth bug traceable to an override that returns around the main search. It fires
     only when the listed root is a strictly longer prefix of the word than the root the
     core chose, and only if segTail() can cover the whole remainder. If the cover fails,
     the core's analysis stands. */
  if(P.segTail){
    for(const ar of ADD_ROOTS){
      if(ar.length<=root.length) continue;
      if(!w.startsWith(ar)) continue;
      let tail=null; try{ tail=P.segTail(w.slice(ar.length)); }catch(e){}
      if(!tail) continue;
      root=ar; ms=tail; break;
    }
  }
  /* build71: pew- is never the sprout root before -tu-. The analyst's ruling is that
     pe-w- 'see one another' and pew- 'sprout' are two lexemes decided by context, and the
     corpus decides every -tu- case: all 148 AVENUE pewtu- tokens translate with
     examination or plain seeing verbs, none with sprouting, and the sprout lexeme is
     pewu- anyway. pew is attestedStrong so the ranker preferred it; this re-splits just
     that sequence. Scoped to a following -tu- so the sprout reading is untouched
     elsewhere: pewuy stays pewu-y. */
  if(root==='pew' && ms.length && ms[0] && ms[0].f==='tu'){
    root='pe'; ms=[{f:'w',slot:31}].concat(ms);
  }
  /* build71: PORTMANTEAU was defined and exported in every build from 43 on and never
     referenced, so its seven rules had never fired. Applied here to the tail of the morph
     list: if the concatenation of the final k morphs equals a listed surface, it is
     replaced by that entry's parts. That both merges a sequence the core over-split
     (m + u -> mu) and re-splits one it split at the wrong point (yi + n -> y + in). */
  ms=portmanteau(ms);
  // FIX 1: underlying-vowel normalisation
  ms=restoreUnderlying(root,ms);
  /* build56: carry the enclitic through. detachJoined() in the core sets p.enclitic for
     particles split off the end of a word (dewmayam -> dewma-y + am; lladkütueymu,
     witrakontukerkeeymu -> + mu), and parse43 was returning {root,m,cat,flag} without it,
     so that material vanished from the output with no error. Accuracy effect is nil,
     those three forms are scored wrong either way, but a parser that silently drops
     input would corrupt anything downstream of it. */
  let out={root,m:ms,cat:p.cat,flag:null};
  if(p.enclitic) out.enclitic=p.enclitic;
  /* build70: apply the core's -tu- labelling to the patch layer's own output.
     tuSlot() runs inside core parse(), so any form this layer re-split never reached it:
     23 gold forms across kuniw-, lif-, lladku- and pew- came out with the hardcoded
     slot 33 that the compound branch above writes, and with no gloss at all, which is
     also why the TU_LEX entry for lladku- had never fired despite being in the table
     since build 131. Gold labels lif- and lladku- 36 on six tokens each, so the
     hardcoded 33 was wrong on both. Re-running tuSlot here is the whole fix; it also
     means the return, deliberate and varying flags now reach these forms. */
  if(p.alts) out.alts=p.alts;
  if(p.alt) out.alt=p.alt;
  if(p.flag) out.flag=p.flag;
  /* build81: flag the bare tukunu- stem as needing annotation instead of presenting an
     arbitrary choice as settled. Analyst ruling 2026-10-07: tu-kunu in the indicative,
     both readings open in non-finite forms, "context will tell". The AVENUE Spanish tier
     then showed the competing reading is not tuku-nu- at all. Of the 26 bare-stem types
     (root tu plus -kunu-), 14 translate with a put or place verb, which root tu cannot
     supply (it is the restorative suffix, and as a root it is 'take'); only -tuku- can,
     so those are tuku-kunu- written with one ku. 3 translate with 'take' and are the real
     tu-kunu- 'leave taken'; tukunukefi "Y dejaba tomado el cuerno" shows both morphemes
     in its gloss. 9 are undetermined. tukukunu-, with both ku written, occurs in 8 types
     in the same field in the same proportion, and tukunungeki "se coloca" against
     tukukunungeki "se deja puesto" is the same word spelled both ways.
     The analysis is therefore decided semantically, like the -tu- slot choice (section 27)
     and the tuku compound criterion (section 40.1), so the parser flags rather than
     guesses. Scoped to root==='tu', so the 164 types with another root, where -kunu-
     'dejar' is straightforward, are untouched. */
  /* build82: the build81 flag is withdrawn; see the haplology rewrite before the return. */

  /* build73: -eymu is ONE ending (3>2sg, the charts' -eymew under the mew~mu reduction),
     so two things have to be undone. The core splits it into the inverse -e- plus the
     final -y, and detachJoined() then takes the -mu off as a free particle. Both are
     reversed here when the three pieces are adjacent at the tail. */
  /* build73: -eymu is ONE ending, the charts' 3>2sg -eymew under the mew~mu reduction.
     Two things have to be undone: the core splits it into the inverse -e- plus the final
     -y, and detachJoined() then takes the -mu off as a free particle. This consumes
     exactly the four characters of the ending from the tail, dropping morphs it fully
     covers and keeping the remainder of a partly covered one, so earlier morphs such as
     the -tu- of kuniwtuneymu are left alone. */
  const enc = out.enclitic && (out.enclitic.f || out.enclitic);
  if(/eymu$/.test(w) && (root+out.m.map(x=>x.f).join('')+(enc||''))===w){
    let need=4, ms=out.m.slice(), eaten=(enc||'');
    need-=eaten.length;
    let ok=(eaten==='' || 'eymu'.endsWith(eaten));
    while(ok && need>0 && ms.length){
      const last=ms[ms.length-1];
      if(last.f.length<=need){ need-=last.f.length; eaten=last.f+eaten; ms.pop(); }
      else { const keep=last.f.slice(0,last.f.length-need);
             eaten=last.f.slice(last.f.length-need)+eaten; need=0;
             ms[ms.length-1]={f:keep,slot:last.slot,label:last.label,gloss:last.gloss}; }
    }
    if(need===0 && eaten==='eymu'){
      out.m=ms.concat([{f:'eymu',slot:2,label:'3>2sg portmanteau ending',gloss:'3>2SG',
        note:"one ending, not -e-y plus a free particle mu: the paradigm charts give 3>2sg "+
             "as -eymew and AVENUE translates every elueymu as 'te dio' / 'le dio'"}]);
      if(enc) delete out.enclitic;
    }
  }
  /* build87: nie- and ni- 'have' are allomorphs of one root (analyst ruling 2026-10-13), and
     nietu is nie- plus restorative -tu-. Build 86 added ni to SINGLE_ROOTS, after which ni
     pre-empted nie on nie- words (ni-e-t-u, ni-etew); and nietu-n was already wrong in
     build 85 (Augusta lists nietun, so the root swallowed -tu-). Where the word begins with
     nie and the chosen root is ni with an e-initial first morph, or a longer root beginning
     with nie, take nie and cover the rest with segTail(); if the cover fails, the parse stands. */
  if(w.startsWith('nie') && ((out.root==='ni' && out.m[0] && out.m[0].f[0]==='e') ||
                             (out.root.length>3 && out.root.startsWith('nie')))){
    /* amended 2026-10-13, analyst ruling: nietew is nie-(e)tew, the subordinate portmanteau
       -etew with its e merged into the root's; written with the deleted-vowel notation. */
    let tl=null;
    if(w.slice(3)==='tew') tl=[{f:'(e)tew',slot:6,label:'inverse (IDO) portmanteau, subordinate',gloss:'INV',align:'inverse'}];
    /* same day: niegetew is nie-nge-(e)tew with g written for ng (analyst ruling); the written
       spelling is kept so the analysis reconstructs: nie-ge-(e)tew. -nge- is the passive (23). */
    else if(w.slice(3)==='getew') tl=[{f:'ge',slot:23,label:'passive (-nge-, written g)',gloss:'PASS'},
                                      {f:'(e)tew',slot:6,label:'inverse (IDO) portmanteau, subordinate',gloss:'INV',align:'inverse'}];
    else { try{ tl=P.segTail(w.slice(3)); }catch(e){} }
    if(tl && tl.length && tl.some(x=>x.f==='(e)tew')){ out.root='nie'; out.m=tl; if(out.enclitic) delete out.enclitic; }
    else if(tl && tl.length){ out.root='nie'; out.m=P.flex(P.rootAdjacent(tl,'')); if(out.enclitic) delete out.enclitic; }
  }
  /* build90: word-final -pe is always the 3rd-person imperative (slot 2), never the slot 13
     proximity -pe- (analyst ruling 2026-10-14: "if the word ends in pe and nothing follows, it is
     always imperative 3rd person, i.e. amulepe"). The table carries -pe only at slot 13, so the
     search labelled every final -pe PROX. The stem before -pe is re-parsed on its own (that reading
     is what the wrong slot also distorted: amuwelaya-pe) and kept if it reconstructs with a strongly
     attested root; otherwise only the label changes. */
  if(IMP_PE_REPARSE!==null && /pe$/.test(w) && out.m.length && out.m[out.m.length-1].f==='pe' && !out.enclitic){
    const PE={f:'pe',slot:2,label:'imperative 3rd person',gloss:'IMP.3',imperative:true,
              note:'word-final -pe: 3rd-person imperative (analyst ruling 2026-10-14)'};
    let done=false;
    if(IMP_PE_REPARSE && w.length>4){
      let q=null; try{ q=parse43(w.slice(0,-2),cat,mr,decomp); }catch(e){}
      /* -pe is the ending, so the stem may not itself end in an ending, object or nominaliser (slots 1-6) */
      if(q && !q.enclitic && q.m && P.attestedStrong(q.root) && (!q.m.length || q.m[q.m.length-1].slot>6) &&
         (q.root+q.m.map(x=>x.f).join('')).replace(/\([^)]*\)/g,'')===w.slice(0,-2)){
        out.root=q.root; out.m=q.m.concat([PE]); done=true; }
    }
    if(!done) out.m[out.m.length-1]=Object.assign({},out.m[out.m.length-1],PE);
  }
  if(P.tuSlot) out=P.tuSlot(out);
  /* build82: bare tukunu- is tuku-kunu- with haplology. Analyst ruling 2026-10-07:
     "haplology sounds right. It's the only thing that makes sense within the parameters
     of Mapudungun typology and grammar." The alternatives considered and rejected
     (RANKING_HANDOFF section 47): -nu- negation (most forms finite, none negative in
     context); a root tukun- plus a reflexive -u- (no root tukun- before consonant-initial
     suffixes, and the -u- co-occurs with object -fi- and passive -nge-); typos (the
     one-ku spelling is the majority, 40 tokens in all three varieties, against 5 bare
     tukukunu- tokens in Nguluche only). The tu.ku-ku.nu sequence loses one ku syllable;
     notation tuku-(ku)nu-, which reconstructs to the written form; norm.py's canon()/eq()
     compare it correctly against itself (tested), and score tu(ku)-kunu- and tu-kunu- as
     different analyses, which they are. Slot, label and gloss are those of
     -kunu- in tukukunu-, so the two spellings receive identical analyses apart from the
     parenthesised syllable. Applied last, after the -eymu repair, which checks
     reconstruction against the surface string. Scoped as the build81 flag was: root
     exactly 'tu' with -kunu- first, so compound roots (chalin-tu-kunu-) are untouched. */
  if(out.root==='tu' && out.m.length && out.m[0] && out.m[0].f==='kunu'){
    out.root='tuku';
    out.m=[Object.assign({},out.m[0],{f:'(ku)nu',
      note:'haplology: tuku-kunu- with one ku syllable deleted (written tukunu-)'})].concat(out.m.slice(1));
  }
  /* build83: -tu- directly after -nge- is slot 16, not 33. Analyst ruling 2026-10-08: the
     new-state reading of -tu- on stative stems ('is now X, and was not before') belongs in
     slot 16. Corpus basis (RANKING_HANDOFF section 49): -nge-tu- forms are translated with
     'ahora/ya' in 10.8% of 1,120 AVENUE lines against 2.2% for -nge- without -tu-, and
     -le-/-küle-tu- in 20.9% of 886 against 4.0%, with repetition and return wording rare;
     e.g. ruka-nge-tu-y 'ahora es pura casa lo que era cementerio', kuñifal-nge-tu-y 'ahora
     está desvalida'. -le-/-küle-tu- already came out 16. -nge-tu- came out 33 because the
     search pairs verbaliser -nge-(36) with -tu-(33), a legal order, and rootAdjacent() in
     the core then relabels -nge- as passive 23 on any root not classed as an adjective,
     leaving -tu- at 33 AFTER 23, which the template forbids. 758 corpus tokens had that
     out-of-order sequence. Both ends are fixed together here: the ruling sends -tu- to 16
     whatever slot -nge- received, which also restores order. Scoped to -tu- immediately
     after -nge-; the 28 other out-of-order -tu- 33 tokens (27 after -tu- 16) are left
     alone and recorded. */
  for(let i=1;i<out.m.length;i++){
    const t=out.m[i], pv=out.m[i-1];
    if(t.f==='tu' && t.slot===33 && /^ng(e|\(e\))?$/.test(pv.f)){
      out.m[i]=Object.assign({},t,{slot:16,label:'RESTORATIVE/contin',gloss:'REST',
        note:"new state on a stative -nge- stem ('is now X'): slot 16, analyst ruling 2026-10-08"});
    }
  }
  /* build99: root-adjacent -l- / -ül- is the causative, slot 34 (analyst ruling 2026-10-17: "make -l-
     causative", reversing the 2026-10-16 instruction to leave the VBLZ 36 label). The search was choosing
     36 on native roots (amu-l-, aku-l-, ye-l-, küme-l-) and 34 on Spanish loans (enseña-l-, manda-l-).
     Only the slot and label change, never the segmentation; skipped if the next suffix would then be out
     of order (slot >= 34). Gold v28 moves the same rows (convention change, rule 3). */
  if(CAUS_L && out.m.length && /^(l|ül)$/.test(out.m[0].f) && out.m[0].slot===36 &&
     !(out.m[1] && out.m[1].slot>=34)){
    out.m[0]=Object.assign({},out.m[0],{slot:34,label:'causative',gloss:'CAUS',
      note:'root-adjacent -l- is the causative (analyst ruling 2026-10-17)'});
  }
  /* build100: root-adjacent -el- after a consonant-final root is the causative, slot 34, not the
     benefactive 27 (analyst ruling 2026-10-17: "el should be the causative after a consonant"; kim-el-
     'teach' from kim- 'know'). -lel- and -el- after a vowel stay benefactive, and the nominaliser -el
     (slot 4) is not touched. The same ruling keeps the benefactive -l- (27) on the loan stems gold labels
     27 (kita-l-, manda-l-, ele-l-, enseña-l-eneu, levanta-l-); build 99 does not reach those, since it only
     relabels a 36. Label only; segmentation untouched. Gold v29 moves montul-el-a-y 27 -> 34. */
  if(CAUS_EL && out.m.length && out.m[0].f==='el' && out.m[0].slot===27 && /[^aeiouü]$/.test(out.root) &&
     !(out.m[1] && out.m[1].slot>=34)){
    out.m[0]=Object.assign({},out.m[0],{slot:34,label:'causative',gloss:'CAUS',
      note:'-el- after a consonant-final root is the causative (analyst ruling 2026-10-17)'});
  }
  /* build103: root-adjacent -l- is the benefactive, slot 27, on these five Spanish loan stems (analyst
     rulings 2026-10-17, the five gold rows labelled 27 "are benefactive", and 2026-10-19, "both enseña-
     examples should be benefactive"). Overrides build 99's causative on exactly these roots; scoped to the
     ruled stems because nothing in the word form separates a benefactive from a causative -l-. Gold v30
     moves enseña-l-nge-n 34 -> 27. */
  if(out.m.length && out.m[0].f==='l' && BEN_L_STEMS.has(out.root) && out.m[0].slot!==27 &&
     !(out.m[1] && out.m[1].slot>=27)){
    out.m[0]=Object.assign({},out.m[0],{slot:27,label:'beneficiary',gloss:'BEN',
      note:'-l- on this loan stem is the benefactive (analyst rulings 2026-10-17, 2026-10-19)'});
  }
  return out;
}
/* build106: ele- is listed as an allomorph of elün 'poner' (analyst ruling 2026-10-24: "ele could probably be listed as
   an allomorph of elün for now"). Same gloss as Augusta's elün; the app shows the source as an analyst ruling. */
/* build116: adüm- has no entry in the Augusta extract. Gloss from the AVENUE Spanish translation tier (src 'C'): adümi 'aprendió',
   adüm l'awen 'sabe hacer remedio', adümal 'conocer', adümlay 'no saben', adümüwün 'atinar, arreglárselas'. */
if(P.GLOSS && !P.GLOSS['wirar']){ P.GLOSS['wirar']={d:'Gritar',src:'R'}; P.GLOSS['wirarwirar']={d:'Gritar (reduplicado: gritar repetidamente)',src:'R'}; }   /* build125 */
if(P.GLOSS){ for(const k of ['feypi','veypi']) if(!P.GLOSS[k]) P.GLOSS[k]={d:'Decir (alomorfo de pi- al inicio de oración o cláusula)',src:'R'}; }   /* build124 */
if(P.GLOSS && !P.GLOSS['adüm']) P.GLOSS['adüm']={d:'Aprender, saber (hacer), entender, manejar; con -üw-: atinar, arreglárselas',src:'C'};
if(P.GLOSS && !P.GLOSS.ele) P.GLOSS.ele={d:P.GLOSS['elün']?P.GLOSS['elün'].d:'Poner',src:'R',allo:'elün'};
const BEN_L_STEMS=new Set(['enseña','kita','manda','levanta','ele','dewma']);   /* build113: dewma-l- 'make for someone' is benefactive; kim-el- 'teach' stays causative 34 (analyst ruling 2026-10-27) */
let CAUS_EL=true; function setCausEl(v){ CAUS_EL=v; }   /* build100; false restores build 99 (A/B only) */
let CAUS_L=true; function setCausL(v){ CAUS_L=v; }   /* build99; false restores build 98 (A/B only) */

/* ===========================================================================================
   build104: NON-VERBAL ANALYSIS (adjectives, adverbs, nouns, postpositional forms).
   Design rulings (Brandon, 2026-10-20): function labels with NO slot numbers; scope adjectives,
   adverbs, nouns and postpositions; automatic detection with a word-class override; rules
   built after a blind annotation (nonverbal_2026-10_annotation, returned 2026-10-24, 90 scorable
   forms in nonverbal_gold_v1.csv). The analyses below follow that annotation's conventions:
     -ke   pluralises adjectives (lig-ke, wecha-ke, wesa-ke)          -> PL
     -che  makes a person noun (füta-ke-che, tripa-che)                -> PERS
     -chi  adjectivises / adverbialises (pichi-chi, fey-ke-chi)         -> ATTR
     -nge-chi on a noun/adjective/verb (newe(n)-nge-chi, pi-nge-chi)   -> VBLZ|PASS + ATTR
     -(y)em on a noun: deceased or no longer (ñuke-yem, chaw-em)        -> FORMER
     -em after a verb's -y-: llankü-y-em, küymi-y-em                    -> EM (analyst: "repeated action")
     -we on a noun: the place of the thing (ruka-we)                    -> PLACE
     mu / mew / meu after a noun is a separate word (mapu meu); after a demonstrative it is part of
       an adverb (ta-meu, fey-ti-mu, tiy-mu)                            -> POSTP / ADV
     lexicalised adverbs and quantifiers stay whole (femngechi, chungechi, fanten, alüke, chemu).
   Exact-word lists are kept small and say where they come from. Everything here is measured
   IN-SAMPLE on the same 90 forms, so it is not an out-of-sample figure.
   =========================================================================================== */
const NV_LEX={  /* whole words: lexicalised adverbs, quantifiers, particles (annotation 2026-10-24, plus spelling variants) */
  /* -ngechi adverbs: only the four the 2026-10-24 annotation keeps whole. Gold v30 splits femngechi, famngechi, vemngechi,
     chumngechi and kangechi as X-nge-chi, so those are left to the X-nge-chi rule until the two conventions are reconciled. */
  adverb:['femengechi','chungechi','feyngechi','fengechi',
          'chemu','awe','afkentu','petu','rume','welu','kuyfi'],
  quantifier:['fanten','fenten','venten','vanten','tunten','chunten'],
  particle:['awem','yem','chi','may','llemay','llemai','kay','am','anta','nga','ka'],
  adjective:['alüke','llenoanchi'],
  /* build115: words the analyst classed as non-verbal in the annotation sheets (nonverbal 2026-10-24, blind set 2 2026-10-27) that no
     rule reached; nouns are mostly Spanish-origin or plant/kin words, which have no morphological signal */
  noun:['make','santu','mama','llanten','piuke','chachay','guagua','llagllag','llavllav','kefra','farmasia','rakiduam','ñukentu','kuchillu',
        'mewülen','wingkadungu','lelfün'],
  numeral:['koñintu'],
  /* build123: class labels for the commonest function words, so sentence mode can name them (no segmentation change) */
  pronoun:['iñche','inche','eymi','iñchiñ','inchiñ','eymün','iñchiu','inchiu','eymu','feyengün','feyengu'],
  possessive:['ñi','mi','ni','iñ'],
  other:['chichi'],
  demonstrative:['tufichi','tüfichi']};
NV_LEX.adverb.push('doy','petu','feula','fewla','müten','chemuchi','tunteke','tritran','kiñepchi','kiñepchin','llemaychi');
const NV_WHOLE={}; for(const [c,ws] of Object.entries(NV_LEX)) for(const w of ws) NV_WHOLE[w]=c;
const NV_ADJ=new Set(['füta','fücha','pütra','pucha','kiñe','lig','wecha','wesa','kidu','kutran','pichi','küme','weche','fütra',
  /* build109: spelling variants and one more adjective seen in blind set 2 (püta-ke-che, pta-ke-che, piche-ke-che, kuyfi-ke-che) */
  'püta','pta','piche','kuyfi']);
const NV_DEM=new Set(['fey','vey','tüfa','tüva','tiye','ta','tiy','feyti','veyti','feyta','veyta']);
const NV_KIN=new Set(['chaw','ñuke','chachay','papay','laku','kuku','chuchu','lamngen','peñi','fotüm','ñawe','wenüy','kure','füta']);
const NVL={POSS:'possessive',PL:'plural',PERS:'person noun',ATTR:'attributive / adverbial',VBLZ:'verbalizer',PASS:'passive',FORMER:'deceased / no longer',
           EM:'em (analyst: repeated action)',PLACE:'place of',POSTP:'postposition',ADV:'adverb-forming',IND:'indicative',DEM:'demonstrative',AGT:'agentive (performer of the verb)',POSS:'possessive (person of the possessor)',MANNER:'adverb of manner (-kechi)'};
const nvm=(f,g,note)=>({f:f,slot:null,gloss:g,label:NVL[g]||g,nonverbal:true,note:note});
function nvDef(w){ const g=P.GLOSS&&(P.GLOSS[w]); return g&&g.src!=='L'?g.d:null; }
function nvIsNounish(w){ if(NV_WHOLE[w]==='noun') return true; const d=nvDef(w); return !!(d && !isVerbDef(d)); }
/* the same test across the spellings AVENUE and Augusta disagree on (lonko/longko, piuke/piwke) */
function nvVariants(w){ return [w, w.replace(/nk/g,'ngk'), w.replace(/([aeiou])u/g,'$1w'), w.replace(/nk/g,'ngk').replace(/([aeiou])u/g,'$1w')]; }
function nvIsNounishV(w){ return nvVariants(w).some(nvIsNounish); }
function nvClassOfDef(d){ if(!d) return 'noun'; if(/^dem\./i.test(d)) return 'demonstrative'; if(/^(interrog|adv)\./i.test(d)) return 'adverb';
  if(/^(el|la|los|las|lo|un|una)\s/i.test(d)) return 'noun';
  if(/^(uno|dos|tres|cuatro|cinco)\b/i.test(d)) return 'quantifier';
  /* a one-word gloss ('Grande', 'Blanco', 'Enfermo') reads as an adjective; a phrase ('Jarro de barro', 'Instrumento de soplo') as a noun */
  const first=d.replace(/^(Huapi|Pangui|Imp|fig)\.\s*/,'').split(/[.,;:(]/)[0].trim();
  return /\s/.test(first) ? 'noun' : 'adjective'; }
function nvVerbal(w){ try{ return parse43v(w,'',3,false); }catch(e){ return null; } }
function nvSegWords(p){ return p.words? p.words : [[p.root].concat((p.m||[]).map(x=>x.f)).join('-')]; }
/* build105: -ngechi adverbs are not split (analyst ruling 2026-10-24: "ngechi adverbs should not be split. I changed my
   mind as I was coding"). Covers the deictic and interrogative bases; X-nge-chi on a lexical noun, adjective or verb
   (newe(n)-nge-chi, kutran-nge-chi, pi-nge-chi) stays split as annotated. Gold v31 moves the five gold rows. */
