    var SUFS=/^(la|ke|ki|a|ya|le|li|pa|pu|tu|fu|nie|nge|we|me|pe|ka|el|w|l|ye|rke|ürke|no|nu|kil|küle|yaw|ñma|ma)$/;
    var stuck=false; for(var kk=2;kk<p.root.length;kk++){ if(rootSense(p.root.slice(0,kk), GLOSS) && SUFS.test(p.root.slice(kk))) { stuck=kk; break; } }
