    var chain=[];               /* auxiliaries, outermost first */
    var advs=[], pre=[], neg=false, fut=false, ipd=false, passive=false, refl=!!sense.refl, io=false, cmpd=[];
    var steps=[], caveatIpd=false, yaNo=false, hadVblz=false, impersonal=false, causSeen=false, reflSuf=false, seImp=false;
    if(rootCmpd){ cmpd.push(rootCmpd.s.verb?rootCmpd.s.inf:rootCmpd.s.text);
                  steps.push('raíz compuesta: '+p.root.slice(0,p.root.length-rootCmpd.f.length)+' + '+rootCmpd.f+' («'+rootCmpd.s.text+'»)'); }
